import { Controller, Get, Post, HttpCode, Req } from '@nestjs/common';
import type { Request } from 'express';
import * as checks from '../common/checks';
import { transaction } from '../common/db';
import { ApiError } from '../common/errors';
import { currentUser } from '../common/user';

const DATE_PATTERN = /^\d{4}-\d{2}-\d{2}$/;

function invalidTrip(message: string): ApiError {
  return new ApiError(422, 'INVALID_TRIP_PERIOD', message);
}

function toId(value: unknown): number | null {
  if (typeof value !== 'number' && typeof value !== 'string') {
    return null;
  }
  if (typeof value === 'string' && value.trim() === '') {
    return null;
  }
  const n = Number(value);
  return Number.isInteger(n) && n > 0 ? n : null;
}

function text(value: unknown): string {
  return typeof value === 'string' ? value.trim() : '';
}

@Controller('api/v1')
export class FnSfr01807Controller {
  @Post('/attendance-requests/trips')
  @HttpCode(200)
  async createTripRequest(@Req() req: Request) {
    const user = currentUser(req);
    user.require('임직원', '근태 담당자');
    const data = checks.inputOf(req.body);
    const attendanceTypeId = toId(data['attendanceTypeId']);
    const tripCategory = text(data['tripCategory']);
    const startDate = text(data['startDate']);
    const endDate = text(data['endDate']);
    const tripPlace = text(data['tripPlace']);
    const reason = text(data['reason']);
    const rawTravelers = data['travelers'];
    if (attendanceTypeId === null) {
      throw invalidTrip('근태항목을 선택해 주세요.');
    }
    if (tripCategory !== '출장' && tripCategory !== '외근') {
      throw invalidTrip('출장·외근 구분을 선택해 주세요.');
    }
    if (!DATE_PATTERN.test(startDate) || !DATE_PATTERN.test(endDate)) {
      throw invalidTrip('시작일과 종료일을 YYYY-MM-DD 형식으로 입력해 주세요.');
    }
    if (tripPlace === '' || tripPlace.length > 200) {
      throw invalidTrip('장소를 200자 이내로 입력해 주세요.');
    }
    if (reason.length > 1000) {
      throw invalidTrip('사유는 1000자 이내로 입력해 주세요.');
    }
    if (!Array.isArray(rawTravelers) || rawTravelers.length === 0) {
      throw invalidTrip('출장자를 한 명 이상 입력해 주세요.');
    }
    const travelers: { employeeId: number; transport: string }[] = [];
    const seen = new Set<number>();
    for (const item of rawTravelers) {
      const row = (item ?? {}) as Record<string, unknown>;
      const employeeId = toId(row['employeeId']);
      const transport = text(row['transport']);
      if (employeeId === null) {
        throw invalidTrip('출장자를 선택해 주세요.');
      }
      if (transport.length > 100) {
        throw invalidTrip('이동수단은 100자 이내로 입력해 주세요.');
      }
      if (seen.has(employeeId)) {
        throw invalidTrip('같은 출장자를 중복해서 넣을 수 없습니다.');
      }
      seen.add(employeeId);
      travelers.push({ employeeId, transport });
    }
    return transaction(async (db) => {
      const period = await db.query(
        'SELECT CAST(:endDate AS date) >= CAST(:startDate AS date) AS ok',
        { startDate, endDate },
      );
      if (!period[0] || period[0]['ok'] !== true) {
        throw invalidTrip('종료일은 시작일보다 빠를 수 없습니다.');
      }
      const types = await db.query(
        'SELECT attendance_type_id FROM attendance_type WHERE attendance_type_id = CAST(:id AS bigint)',
        { id: attendanceTypeId },
      );
      if (types.length === 0) {
        throw invalidTrip('존재하지 않는 근태항목입니다.');
      }
      for (const t of travelers) {
        const found = await db.query(
          'SELECT employee_id FROM employee WHERE employee_id = CAST(:id AS bigint)',
          { id: t.employeeId },
        );
        if (found.length === 0) {
          throw invalidTrip('존재하지 않는 출장자입니다.');
        }
      }
      // 가정: 신청 시 결재 상태는 기안으로 저장한다. 전자결재 상신은 공통 모듈(P3)이 맡는다.
      const rows = await db.query(
        'INSERT INTO attendance_request (employee_id, attendance_type_id, start_date, end_date, reason, trip_category, trip_place, approval_status, created_at, updated_at) ' +
          'VALUES (CAST(:userId AS bigint), CAST(:typeId AS bigint), CAST(:startDate AS date), CAST(:endDate AS date), :reason, :tripCategory, :tripPlace, :status, now(), now()) ' +
          'RETURNING attendance_request_id AS "attendanceRequestId", approval_status AS "approvalStatus"',
        {
          userId: user.id,
          typeId: attendanceTypeId,
          startDate,
          endDate,
          reason: reason === '' ? null : reason,
          tripCategory,
          tripPlace,
          status: '기안',
        },
      );
      const created = rows[0];
      for (const t of travelers) {
        await db.execute(
          'INSERT INTO trip_traveler (attendance_request_id, employee_id, transport, created_at, updated_at) ' +
            'VALUES (CAST(:requestId AS bigint), CAST(:employeeId AS bigint), :transport, now(), now())',
          {
            requestId: created['attendanceRequestId'],
            employeeId: t.employeeId,
            transport: t.transport === '' ? null : t.transport,
          },
        );
      }
      return created;
    });
  }

  @Get('/attendance-requests/trips')
  async listTripRequests(@Req() req: Request) {
    const user = currentUser(req);
    user.require('임직원', '근태 담당자');
    const q = checks.queryOf(req.query);
    const startDate = text(q['startDate']);
    const endDate = text(q['endDate']);
    const departmentRaw = text(q['departmentId']);
    const employeeRaw = text(q['employeeId']);
    const invalidSearch = (message: string) => new ApiError(422, 'INVALID_SEARCH_PERIOD', message);
    if ((startDate !== '' && !DATE_PATTERN.test(startDate)) || (endDate !== '' && !DATE_PATTERN.test(endDate))) {
      throw invalidSearch('조회 기간을 YYYY-MM-DD 형식으로 입력해 주세요.');
    }
    const departmentId = departmentRaw === '' ? null : toId(departmentRaw);
    const employeeId = employeeRaw === '' ? null : toId(employeeRaw);
    if ((departmentRaw !== '' && departmentId === null) || (employeeRaw !== '' && employeeId === null)) {
      throw new ApiError(400, 'VALIDATION_FAILED', '부서·사원 값이 올바르지 않습니다.');
    }
    const pageNo = Math.max(0, Number.parseInt(text(q['page']), 10) || 0);
    const sizeRaw = Number.parseInt(text(q['size']), 10);
    const size = Math.min(200, sizeRaw > 0 ? sizeRaw : 20);
    return transaction(async (db) => {
      if (startDate !== '' && endDate !== '') {
        const check = await db.query(
          'SELECT CAST(:startDate AS date) > CAST(:endDate AS date) AS bad',
          { startDate, endDate },
        );
        if (check[0] && check[0]['bad'] === true) {
          throw invalidSearch('조회 시작일이 종료일보다 늦을 수 없습니다.');
        }
      }
      const from =
        ' FROM attendance_request r' +
        ' JOIN trip_traveler t ON t.attendance_request_id = r.attendance_request_id' +
        ' JOIN employee e ON e.employee_id = t.employee_id' +
        ' WHERE r.trip_category IS NOT NULL' +
        ' AND (:startDate IS NULL OR r.end_date >= CAST(:startDate AS date))' +
        ' AND (:endDate IS NULL OR r.start_date <= CAST(:endDate AS date))' +
        ' AND (:departmentId IS NULL OR e.department_id = CAST(:departmentId AS bigint))' +
        ' AND (:employeeId IS NULL OR t.employee_id = CAST(:employeeId AS bigint))';
      const filter = {
        startDate: startDate === '' ? null : startDate,
        endDate: endDate === '' ? null : endDate,
        departmentId,
        employeeId,
      };
      const items = await db.query(
        'SELECT r.attendance_request_id AS "attendanceRequestId", r.trip_category AS "tripCategory", ' +
          'r.start_date AS "startDate", r.end_date AS "endDate", r.trip_place AS "tripPlace", ' +
          'r.approval_status AS "approvalStatus", t.employee_id AS "travelerEmployeeId", t.transport AS "transport"' +
          from +
          ' ORDER BY r.attendance_request_id DESC, t.trip_traveler_id' +
          ' LIMIT CAST(:size AS int) OFFSET CAST(:offset AS int)',
        { ...filter, size, offset: pageNo * size },
      );
      const counted = await db.query('SELECT COUNT(*) AS "total"' + from, filter);
      const total = Number(counted[0]['total']);
      return { items, page: pageNo, size, total };
    });
  }
}

