import { useState } from 'react';
import {
  PageProps,
  Row,
  call,
  useData,
  Page,
  Badge,
  DateText,
  Filters,
  Band,
  DataTable,
  Pager,
  Drawer,
  Tiles,
  Num,
  Form,
  Field,
  TextInput,
  DateInput,
  Select,
  LookupSelect,
  RefName,
  ErrorText,
} from '../kit';

interface TravelerForm {
  employeeId: number | string;
  transport: string;
}

const EMPTY_TRAVELER: TravelerForm = { employeeId: '', transport: '' };

export default function FnSfr01807Page({ role, notify }: PageProps) {
  const [startDate, setStartDate] = useState('');
  const [endDate, setEndDate] = useState('');
  const [departmentId, setDepartmentId] = useState<number | string>('');
  const [employeeId, setEmployeeId] = useState<number | string>('');
  const [applied, setApplied] = useState<Row>({});
  const [pageNo, setPageNo] = useState(0);
  const [open, setOpen] = useState(false);

  const [attendanceTypeId, setAttendanceTypeId] = useState<number | string>('');
  const [tripCategory, setTripCategory] = useState('');
  const [formStart, setFormStart] = useState('');
  const [formEnd, setFormEnd] = useState('');
  const [tripPlace, setTripPlace] = useState('');
  const [reason, setReason] = useState('');
  const [travelers, setTravelers] = useState<TravelerForm[]>([{ ...EMPTY_TRAVELER }]);

  const { data, error, reload } = useData<Page>(
    () => call<Page>('GET', '/attendance-requests/trips', role, undefined, { ...applied, page: pageNo, size: 20 }),
    [applied, pageNo, role],
  );

  function search() {
    setPageNo(0);
    setApplied({ startDate, endDate, departmentId, employeeId });
  }

  function reset() {
    setStartDate('');
    setEndDate('');
    setDepartmentId('');
    setEmployeeId('');
    setPageNo(0);
    setApplied({});
  }

  function openForm() {
    setAttendanceTypeId('');
    setTripCategory('');
    setFormStart('');
    setFormEnd('');
    setTripPlace('');
    setReason('');
    setTravelers([{ ...EMPTY_TRAVELER }]);
    setOpen(true);
  }

  function changeTraveler(index: number, patch: Partial<TravelerForm>) {
    setTravelers(travelers.map((t, i) => (i === index ? { ...t, ...patch } : t)));
  }

  async function submit() {
    if (attendanceTypeId === '' || tripCategory === '' || formStart === '' || formEnd === '' || tripPlace.trim() === '') {
      throw new Error('근태항목, 구분, 기간, 장소를 모두 입력해 주세요.');
    }
    if (formEnd < formStart) {
      throw new Error('종료일은 시작일보다 빠를 수 없습니다.');
    }
    if (travelers.length === 0 || travelers.some((t) => t.employeeId === '')) {
      throw new Error('출장자를 선택해 주세요.');
    }
    await call('POST', '/attendance-requests/trips', role, {
      attendanceTypeId,
      tripCategory,
      startDate: formStart,
      endDate: formEnd,
      tripPlace,
      reason,
      travelers: travelers.map((t) => ({ employeeId: t.employeeId, transport: t.transport })),
    });
    notify('출장·외근 신청을 등록했습니다.');
    setOpen(false);
    setPageNo(0);
    reload();
  }

  const rows = data?.items ?? [];

  return (
    <div className="bento">
      <section className="box span-12">
        <h2>조회 건수</h2>
        <Tiles items={[['출장·외근 상세내역', <Num value={data?.total ?? 0} />]]} />
      </section>
      <section className="box span-12">
        <h2>출장·외근 내역</h2>
        <Filters onSearch={search} onReset={reset}>
          <Field label="조회 시작일">
            <DateInput value={startDate} onChange={setStartDate} />
          </Field>
          <Field label="조회 종료일">
            <DateInput value={endDate} onChange={setEndDate} />
          </Field>
          <Field label="부서">
            <LookupSelect table="department" role={role} value={departmentId} onChange={setDepartmentId} />
          </Field>
          <Field label="사원">
            <LookupSelect table="employee" role={role} value={employeeId} onChange={setEmployeeId} />
          </Field>
        </Filters>
        {error ? <ErrorText text={error} /> : null}
        <Band total={data?.total}>
          <button type="button" onClick={openForm}>출장·외근 신청</button>
        </Band>
        <DataTable
          rows={rows}
          empty="조회된 출장·외근 내역이 없습니다."
          columns={[
            { key: 'attendanceRequestId', label: '근태 신청 ID' },
            { key: 'tripCategory', label: '출장·외근 구분' },
            { key: 'startDate', label: '시작일', render: (r) => <DateText value={r.startDate} /> },
            { key: 'endDate', label: '종료일', render: (r) => <DateText value={r.endDate} /> },
            { key: 'tripPlace', label: '장소' },
            { key: 'approvalStatus', label: '결재 진행 상태', render: (r) => <Badge value={r.approvalStatus} /> },
            {
              key: 'travelerEmployeeId',
              label: '출장자',
              render: (r) => <RefName table="employee" role={role} value={r.travelerEmployeeId} />,
            },
            { key: 'transport', label: '이동수단' },
          ]}
        />
        <Pager page={data?.page ?? 0} size={data?.size ?? 20} total={data?.total ?? 0} onPage={setPageNo} />
      </section>
      {open ? (
        <Drawer title="출장·외근 신청" onClose={() => setOpen(false)}>
          <Form onSubmit={submit} submit="신청">
            <Field label="근태항목" required>
              <LookupSelect table="attendance_type" role={role} value={attendanceTypeId} onChange={setAttendanceTypeId} />
            </Field>
            <Field label="출장·외근 구분" required>
              <Select
                value={tripCategory}
                onChange={setTripCategory}
                options={[['출장', '출장'], ['외근', '외근']]}
              />
            </Field>
            <Field label="시작일" required>
              <DateInput value={formStart} onChange={setFormStart} />
            </Field>
            <Field label="종료일" required>
              <DateInput value={formEnd} onChange={setFormEnd} />
            </Field>
            <Field label="장소" required wide>
              <TextInput value={tripPlace} onChange={setTripPlace} />
            </Field>
            <Field label="사유" wide>
              <TextInput value={reason} onChange={setReason} multiline />
            </Field>
            {travelers.map((t, index) => (
              <Field key={index} label={'출장자 ' + (index + 1)} required wide>
                <LookupSelect
                  table="employee"
                  role={role}
                  value={t.employeeId}
                  onChange={(v) => changeTraveler(index, { employeeId: v })}
                />
                <TextInput
                  value={t.transport}
                  onChange={(v) => changeTraveler(index, { transport: v })}
                  placeholder="이동수단"
                />
                {travelers.length > 1 ? (
                  <button type="button" onClick={() => setTravelers(travelers.filter((_, i) => i !== index))}>
                    삭제
                  </button>
                ) : null}
              </Field>
            ))}
            <button type="button" onClick={() => setTravelers([...travelers, { ...EMPTY_TRAVELER }])}>
              출장자 추가
            </button>
          </Form>
        </Drawer>
      ) : null}
    </div>
  );
}
